declare const idBrand: unique symbol
type UserId = string & { readonly [idBrand]: 'UserId' }
type OrderId = string & { readonly [idBrand]: 'OrderId' }

function parseUserId(value: string): UserId {
  if (!/^user_[a-z0-9]+$/.test(value)) throw new TypeError('Неверный UserId')
  return value as UserId
}
// Функция, принимающая UserId, не должна принимать OrderId.

async function request<T>(url: string, parse: (value: unknown) => T): Promise<T> {
  const response = await fetch(url)
  if (!response.ok) throw new Error('HTTP ' + response.status)
  const raw: unknown = await response.json()
  return parse(raw)
}
// Тип результата определяется parse, а не произвольным as T внутри request.

type Result<T, E> = { ok: true; value: T } | { ok: false; error: E }
type FindError = 'not-found' | 'forbidden'

function label(result: Result<{ name: string }, FindError>): string {
  if (result.ok) return result.value.name
  return result.error === 'not-found' ? 'Не найдено' : 'Нет доступа'
}
// Promise<Result<T, E>> описывает ожидаемые исходы,
// но сам по себе не запрещает неожиданное отклонение Promise.

